import java.util.Arrays

class AvoidMultipleConcatStatementsKt {
    fun testMultipleConcatDefect() {
        var logStatement = ""
        val values = Arrays.asList(*arrayOf("tic", "tac", "toe"))
        logStatement += values[0]
        logStatement += values[1] // bad 8
    }

    fun testMultipleConcatCorrect() {
        var log = 0
        val values = listOf(1, 2, 3)
        log += values[0]
        log += values[1]
    }

    fun testMultipleConcatDefect2() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0]
        logStatement = logStatement + values[1] // bad 22
    }

    fun testMultipleConcatCorrect2() {
        var log = 0
        val values = arrayOf(1, 2, 3)
        log = log + values[0]
        log = log + values[1]
    }

    fun testMultipleConcatDefect3() {
        var logStatement = "info: "
        val values = listOf("tic", "tac", "toe")
        logStatement += 2
        logStatement += values[1] // bad 36
    }

    fun testMultipleConcatCorrect3() {
        var log = 0
        val values = listOf(1, 2, 3)
        log += 2
        log += values[1]
    }

    fun testMultipleConcatDefect4() {
        var log = ""
        var i = 0
        val values = listOf(1, 2, 3)
        while (i++ < 3) {
            log = log + values[0]
            log = log + values[1] // bad 51
        }
    }

    fun testMultipleConcatCorrect4() {
        var log = 0
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1]
        }
    }

    fun testMultipleConcatDefect5() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0]
        logStatement += values[1] // bad 69
    }

    fun testMultipleConcatCorrect5() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0] + values[1]
    }

    fun testMultipleConcatDefect6() {
        var log = someString();
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1] //bad 84
        }
    }

    fun testMultipleConcatCorrect6() {
        var log = someInt("");
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1]
        }
    }

    fun testMultipleConcatDefect7() {
        var logStatement: String = someUnknown();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 102
    }

    fun testMultipleConcatCorrect7() {
        var logStatement: String = someUnknown();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0] + values[1]
    }

    fun testMultipleConcatDefect8() {
        var logStatement = "{"
        val values = listOf("tic", "tac", "toe")
        logStatement += "$values[0], "
        logStatement += "$values[1]}" // bad 115
    }

    fun testMultipleConcatCorrect8() {
        var logStatement = "{"
        val values = listOf("tic", "tac", "toe")
        logStatement += "$values[0], $values[1]}"
    }

    fun testMultipleConcatDefect9(first: String) {
        var logStatement = first;
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 128
    }

    fun testMultipleConcatCorrect9(first: Int) {
        var logStatement = first;
        val values = listOf(1, 2, 3)
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect10() {
        var logStatement = someString();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 142
    }

    fun testMultipleConcatCorrect10() {
        var logStatement = someInt("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect11() {
        var logStatement = someString(someString());
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 156
    }

    fun testMultipleConcatCorrect11() {
        var logStatement = someInt(someString());
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect12() {
        var logStatement = someString("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 170
    }

    fun testMultipleConcatCorrect12() {
        var logStatement = someString("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0] + values[1]
    }

    private fun someString(): String {
        return "";
    }

    private fun someString(str: String): String {
        return str;
    }

    private fun someInt(str: String): Int {
        return 0;
    }
}

class Foo(private val isActive: Boolean, private val canCreate: Boolean) {

    private fun calculate(myList: List<String>): List<String> {

        val mutableList = myList.toMutableList()

        if (isActive) {
            mutableList += "one" // false positive, not two lines with += are needed to trigger this rule
            if (canCreate) {
                mutableList += listOf("two", "three") // false positive
            }
        } else {
            mutableList.removeAll(listOf("one", "two"))
        }
        return myList
    }
}

import java.math.BigDecimal

data class Vec2(val x: Int, val y: Int) {
    operator fun plus(other: Vec2): Vec2 = Vec2(this.x + other.x, this.y + other.y)
}

class NonStringPlusUsages {

    fun numericPlus(): Int {
        var a = 10
        a += 5
        a = a + 2
        val b = 3 + 4
        return a + b
    }

    fun bigDecimalPlus(): BigDecimal {
        var total = BigDecimal.ZERO
        total += BigDecimal("1.5")
        total = total + BigDecimal("2.25")
        return total + BigDecimal("3.0")
    }

    fun listPlus(x: List<Int>, y: List<Int>): List<Int> {
        var base = listOf(1, 2)
        base = base + 3
        base += listOf(4, 5)
        val more = base + listOf(6)
        val evenMore = x + y
        return more
    }

    fun mutableListPlusAssign(): MutableList<Int> {
        val ml = mutableListOf(1)
        ml += 2
        ml += listOf(3, 4)
        return ml
    }

    fun setUnion(): Set<Int> {
        val s1 = setOf(1, 2)
        val s2 = setOf(2, 3)
        val s3 = s1 + s2
        return s3 + 4
    }

    fun mapPlus(): Map<String, Int> {
        val m1 = mapOf("a" to 1)
        val m2 = m1 + ("b" to 2)
        val m3 = m2 + mapOf("c" to 3)
        return m3
    }

    fun arrayPlus(): IntArray {
        val arr = intArrayOf(1, 2)
        val extended = arr + 3
        return extended + intArrayOf(4, 5)
    }

    fun customOperatorPlus(): Vec2 {
        var v = Vec2(1, 2)
        v += Vec2(3, 4)
        v = v + Vec2(5, 6)
        return v + Vec2(7, 8)
    }
}

class HashCodeSample(
    group1: String,
    group2: String,
    group3: String
) {
    private val group1: String
    private val group2: String
    private val group3: String

    // note: without this line, there is no false positive
    override fun toString(): String = java.lang.String.join(group1, group2, group3)

    override fun hashCode(): Int {
        var result = group1.hashCode()
        result = 31 * result + group2.hashCode()
        result = 31 * result + group3.hashCode() // <-- false positive
        return result
    }
}
